def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            if char == 'X':
                total += 10 * (10 - i)
            else:
                total += int(char) * (10 - i)
        return total % 11

    # Remove hyphens and check if the length is correct
    isbn = isbn.replace('-', '')
    if len(isbn) != 10:
        raise ValueError("Invalid ISBN format")

    # Calculate the expected checksum
    expected_checksum = calculate_checksum(isbn[:9])

    # Compare the calculated checksum with the provided one
    if isbn[-1] == 'X':
        provided_checksum = 10
    else:
        provided_checksum = int(isbn[-1])

    if expected_checksum == provided_checksum:
        return "Right"
    else:
        # Correct the last digit and return the corrected ISBN
        corrected_isbn = isbn[:-1] + ('X' if expected_checksum == 0 else str(expected_checksum))
        return corrected_isbn

