def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if not (1 <= M <= 1000 and 1 <= N <= 1000):
        raise ValueError("M and N must be between 1 and 1000")
    if not (0 <= K <= M and 0 <= L <= N):
        raise ValueError("K and L must be non-negative and K <= M, L <= N")
    if not (0 <= D <= (M * N)):
        raise ValueError("D must be non-negative and D <= M * N")
    if not all(isinstance(pair, tuple) and len(pair) == 4 and 1 <= pair[0] <= M and 1 <= pair[1] <= N and 1 <= pair[2] <= M and 1 <= pair[3] <= N for pair in chatting_pairs):
        raise ValueError("Each chatting pair must be a tuple of four integers within the valid range")

    # Calculate the number of chatting pairs that can be separated by adding an aisle at each possible row and column
    row_separations = [0] * (M + 1)
    col_separations = [0] * (N + 1)

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi and Yi != Qi:
            row_separations[min(Yi, Qi)] += 1
            row_separations[max(Yi, Qi) + 1] -= 1
        elif Yi == Qi and Xi != Pi:
            col_separations[min(Xi, Pi)] += 1
            col_separations[max(Xi, Pi) + 1] -= 1

    # Calculate the cumulative number of separations
    for i in range(1, M + 1):
        row_separations[i] += row_separations[i - 1]
    for j in range(1, N + 1):
        col_separations[j] += col_separations[j - 1]

    # Find the K most effective rows for aisles
    row_indices = sorted(range(1, M + 1), key=lambda i: -row_separations[i])[:K]
    # Find the L most effective columns for aisles
    col_indices = sorted(range(1, N + 1), key=lambda i: -col_separations[i])[:L]

    return (' '.join(map(str, row_indices)), ' '.join(map(str, col_indices)))
