def max_energy(beads):
    n = len(beads)
    if n < 3:
        return 0

    # Create a circular array to handle the circular nature of the necklace
    beads = beads + beads

    # Initialize a DP table
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            if j >= 2 * n:
                break
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][n - 1]

