    for degree in range(n, -1, -1):
        coeff = coeffs[n - degree]
        if coeff == 0:
            continue
        if degree == 0:
            term = f'{abs(coeff)}'
        elif degree == 1:
            term = f'{coeff}x' if abs(coeff) != 1 else 'x'
        else:
            term = f'{coeff}x^{degree}' if abs(coeff) != 1 else f'x^{degree}'
        if coeff < 0:
            if terms:
                term = '-' + term[1:]
            else:
                term = '-' + term
        terms.append(term)
    return ''.join(terms)
