def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or n > k * (k + 1) // 2:
        return 0
    if k == 1:
        return 1

    memo = [[-1 for _ in range(k + 1)] for _ in range(n + 1)]

    def dp(i, m):
        if i == n and m == k:
            return 1
        if i > n or m > k or i < m * x:
            return 0
        if memo[i][m] != -1:
            return memo[i][m]

        memo[i][m] = dp(i - m, m) + dp(i - m - 1, m - 1)
        return memo[i][m]

    return dp(n, k)
```

