def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, k):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord(k) - ord('a')) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord(k) - ord('A')) % 26 + ord('A'))
        else:
            raise ValueError("Ciphertext must consist only of alphabetic characters")

    key_length = len(key)
    decrypted_text = []

    for i, c in enumerate(ciphertext):
        k = key[i % key_length]
        d = shift_char(c, k)
        decrypted_text.append(d)

    return ''.join(decrypted_text)
